# Go Web Server with GET and POST Endpoints

Below is a complete Go web server using modular file structure and robust best practices including middleware, JSON handling, and graceful shutdowns.

---

## ✅ File Structure Overview

```
main.go                    // Entry point and server logic
handlers.go                // Endpoint handlers
middleware.go              // Logging, CORS, etc.
config.go                  // App config and validation
database.go                // Mock database layer
models/user.go             // User model definition
errors.go                  // Custom error types
```

---

## 🧱 Main Application Files

### 1. `main.go`

```go
package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"goapp/handlers"
	"goapp/middleware"
)

func main() {
	config := config.LoadConfig()
	router := setupRouter(config)

	server := &http.Server{
		Addr:         ":" + config.Port,
		Handler:      router,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	// Start server on separate goroutine
	go func() {
		log.Printf("Server starting at http://:%s", config.Port)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("HTTP Server error: %v", err)
		}
	}()

	// Graceful shutdown handler
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Println("Force shutdown:", err)
	}

	log.Println("Server stopped gracefully")
}
```

---

### 2. `handlers/handlers.go`

```go
package handlers

import (
	"encoding/json"
	"fmt"
	"net/http"
)

type Response struct {
	Response string                 `json:"response"`
	Data     map[string]interface{} `json:"data,omitempty"`
	Error    *ErrorResponse         `json:"error,omitempty"`
}

type ErrorResponse struct {
	Message string  `json:"message"`
	Detail  string  `json:"detail,omitempty"`
	Code    int     `json:"code,omitempty"`
}

type GetUserRequest struct{}

func HandleGetUsers(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "Invalid method: expect GET")
		return
	}

	data := map[string]interface{}{
		"name":       "UserList",
		"status":     "success",
		"count":      0,
		"items":      []map[string]interface{}{},
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"data":   data,
		"message": fmt.Sprintf("Retrieved all users (%d)", len(data["items"])),
	})
}

func HandleCreateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "Invalid method: expect POST")
		return
	}

	var req GetUserRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "Invalid request body")
		return
	}

	resp := map[string]interface{}{
		"name":    "New User Created",
		"id":      generateID(),
		"message": "User added successfully",
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(resp)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(ErrorResponse{Message: msg})
}

func generateID() string {
	return fmt.Sprintf("%d", time.Now().UnixNano())
}
```

